def greatest(x,y,z):
    if x >= y and x >= z:
        return x
    elif y >= x and y >= z:
        return y
    return z

l3-greatest-nested:
def greatest_nested(x,y,z):
    if x > y:
        if x > z:
            return x
        else:
            return z
    else:
        if y > z:
            return y
        return z

