l5-valid-name:
import keyword
def validVariable(name):
    if not name:
        return False
    if not (name[0].isalpha() or name[0] == "_"):
        return False
    for ch in name[1:]:
        if not (ch.isalpha() or ch.isdigit() or ch == "_"):
            return False
    return not keyword.iskeyword(name)
